mapper.select:
SELECT current_challenge_id
FROM users
WHERE id = #{userId}

mapper.update:
UPDATE users
SET current_challenge_id = #{challengeId}
WHERE id = #{userId}
  AND current_challenge_id IS NULL

UPDATE users
SET current_challenge_id = NULL
WHERE id = #{userId}
  AND current_challenge_id = #{challengeId}

mapper.select:
SELECT COUNT(*)
FROM challenge
WHERE invite_code = #{inviteCode}
